# Shift -1 promises some solid fills. Let me try combining with color mapping.
# With shift=-1: right[0] maps to output col1, right[1] to col2, etc.

def make_grid_test_shift_with_map(grid, shift=0, mapping=None):
    """Right columns shifted by 'shift' -> output non-8 positions with color map"""
    if mapping is None:
        mapping = {2:2, 3:3, 4:4, 7:7}

    out = [[0]*5 for _ in range(17)]
    for r in range(17):
        left = grid[r][:5]
        right = grid[r][6:]  # 4 cols

        for c in range(5):
            if left[c] != 0:
                out[r][c] = left[c]
            else:
                rhs_idx = c + shift
                rhs_val = right[rhs_idx] if rhs_idx < len(right) else None
                if rhs_val is not None:
                    out[r][c] = mapping.get(rhs_val, 0)
                else:
                    pass
    return out

